// Handle both Telegram and WhatsApp message formats
const data = items[0].json;

let sessionId = null;
let chatInput = null;

// --- TELEGRAM FORMAT ---
// Telegram sends: { message: { chat: { id: ... }, text: "..." } }
if (data.message && data.message.text) {
  sessionId = String(data.message.chat?.id || data.message.from?.id || 'unknown');
  chatInput = data.message.text;
}

// --- WHATSAPP FORMAT ---
// WhatsApp sends: { messages: [{ from: "...", text: { body: "..." } }] }
else if (Array.isArray(data.messages) && data.messages.length > 0) {
  const msg = data.messages[0];
  sessionId = msg.from || null;
  chatInput = msg.text?.body || msg.text || null;
}

// --- STATUS UPDATE (no text, just delivery receipt) ---
else if (!sessionId && Array.isArray(data.statuses) && data.statuses.length > 0) {
  sessionId = data.statuses[0].recipient_id || null;
  chatInput = null;
}

// Safety fallback
if (!chatInput) chatInput = data.text || data.chatInput || '';
if (!sessionId) sessionId = 'session_' + Date.now();

return [
  {
    json: {
      sessionId,
      chatInput,
      text: chatInput  // also set 'text' field so downstream nodes work
    }
  }
];

// Loop over input items and change the MIME type of binary data
for (const item of $input.all()) {
  // Check if the item has binary data
  if (item.binary) {
    // Find the binary property name (assuming there's at least one)
    const binaryPropertyNames = Object.keys(item.binary);

    for (const propName of binaryPropertyNames) {
      // If the MIME type is 'audio/mp3', change it to 'audio/mpeg'
      if (item.binary[propName].mimeType === "audio/mp3") {
        item.binary[propName].mimeType = "audio/mpeg";
      }
    }
  }
}

return $input.all();

// Get the AI Agent output
const aiOutput = $input.first().json.output;

// Function to clean the text
function cleanAIResponse(text) {
  let cleaned = text;

  // Remove all asterisks (single, double, or multiple)
  cleaned = cleaned.replace(/\*+/g, '');

  // Remove markdown headers (##, ###, etc.)
  cleaned = cleaned.replace(/^#+\s*/gm, '');

  // Remove markdown bold (**text** or __text__)
  cleaned = cleaned.replace(/\*\*(.+?)\*\*/g, '$1');
  cleaned = cleaned.replace(/__(.+?)__/g, '$1');

  // Remove markdown italic (*text* or _text_)
  cleaned = cleaned.replace(/\*(.+?)\*/g, '$1');
  cleaned = cleaned.replace(/_(.+?)_/g, '$1');

  // Remove markdown strikethrough (~~text~~)
  cleaned = cleaned.replace(/~~(.+?)~~/g, '$1');

  // Remove markdown code blocks (```text```)
  cleaned = cleaned.replace(/```[\s\S]*?```/g, '');
  cleaned = cleaned.replace(/`(.+?)`/g, '$1');

  // Remove extra spaces at line starts
  cleaned = cleaned.replace(/^\s+/gm, '');

  // Remove multiple consecutive blank lines (keep max 2)
  cleaned = cleaned.replace(/\n{3,}/g, '\n\n');

  // Trim leading and trailing whitespace
  cleaned = cleaned.trim();

  return cleaned;
}

// Clean the response
const cleanedOutput = cleanAIResponse(aiOutput);

// Return the cleaned output
return {
  json: {
    output: cleanedOutput,
    original: aiOutput  // Keep original in case you need it
  }
};

